    public static function render(string $name, string $class = 'h-5 w-5', bool $brand = false): string
    {
        $map = $brand ? self::BRANDS : self::PATHS;
        $body = $map[$name] ?? self::PATHS['sparkles'] ?? '';

        $attrs = $brand
            ? 'viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"'
            : 'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"';

        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" %s class="%s">%s</svg>',
            $attrs,
            e($class),
            $body,
        );
    }

    public static function isBrand(string $name): bool
    {
        return array_key_exists($name, self::BRANDS);
    }

    public static function exists(string $name): bool
    {
        return array_key_exists($name, self::PATHS) || array_key_exists($name, self::BRANDS);
    }
}
